  Set retValue = "Unknown"
  set origNS = $NAMESPACE
  set $NAMESPACE = "ITFCOMMON"
  set tsc = $$$OK
  try 
  {
	set servicePort = ##class(MyWebServiceClient.MyWebServiceSoap).%New()

 	Set res = servicePort.Divide(arg1, arg2) 	
	}  
    CATCH exceptionvar
    {
     If $ZERROR["<ZSOAP>" 
     {
            Set retValue= %objlasterror ; $system.OBJ.DisplayError(%objlasterror)
            set tsc = $$$ERROR(retValue)
            if ( retValue["9305" )
            {
	            Set tsc =  ..FailMsgError($CLASSNAME())
            }
            ElseIf ( retValue["9304" )
            {
	            Set tsc =  ..SuspendMsgError($CLASSNAME())
            }
            ElseIf ( retValue["9303" )
            {
	            Set tsc =  ..RetryMsgError($CLASSNAME())
            }
            ElseIf ( retValue["9302" )
            {
	            Set tsc =  ..WarnMsgError($CLASSNAME())
            }
            ElseIf ( retValue["9301" )
            {
	            Set tsc =  ..SkipMsgError($CLASSNAME())
            }
            ElseIf ( retValue["9399" )
            {
	            Set tsc =  ..DisableMsgError($CLASSNAME())
            }
     } 
     Else {
            Set retValue="Other error:" _ $$$ERROR($$$CacheError,$ZERROR)

     }
    }
  set $NAMESPACE = origNS
  Quit tsc

$$$LOGINFO(errCode _ " !!! " _ errMsg)
